<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/session.php';requireAdmin();$r=$conn->query('SELECT id,name,email,created_at FROM users ORDER BY created_at DESC');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="navbar"><a class="logo" href="dashboard.php"><div class="logo-icon">🌿</div><span>Stress<span>Care</span></span></a><div class="nav-links"><a class="nav-btn" href="dashboard.php">Dashboard</a><a class="nav-btn" href="logout.php">Logout</a></div></header><main class="container"><div class="title"><h2>Registered Users</h2></div><div class="card"><div class="table-wrap"><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Registered</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td><?=$x['id']?></td><td><?=htmlspecialchars($x['name'])?></td><td><?=htmlspecialchars($x['email'])?></td><td><?=date('d M Y, h:i A',strtotime($x['created_at']))?></td></tr><?php endwhile;?></table></div></div></main></body></html>
